h=h[:i]+"""function composeNew(n){if(!s.voice){setStatus('Add a voice recording first');return}const ids=GEN.map(g=>g.id).filter(k=>s.gw[k]>0);if(!ids.length){setStatus('Turn up at least one genre in the genre mix');return}const base=selectionSeed(),batch=s.batches[base]=(s.batches[base]||0)+1,R=(a=>()=>{a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296})(base^batch);
const tot=ids.reduce((a,k)=>a+s.gw[k],0),cnt=ids.map(k=>{const x=s.gw[k]/tot*n;return[k,Math.floor(x),x-Math.floor(x)+R()*1e-6]});let left=n-cnt.reduce((a,c)=>a+c[1],0);cnt.sort((a,b)=>b[2]-a[2]);for(let i=0;i<left;i++)cnt[i%cnt.length][1]++;let list=[];for(const[k,c]of cnt)for(let i=0;i<c;i++)list.push(k);list=list.map(k=>[R(),k]).sort((a,b)=>a[0]-b[0]).map(x=>x[1]);
list.forEach((k,i)=>{const sd=(base^Math.imul(batch*16+i+1,0x9E3779B1))>>>0,src=R()*100<s.src?'classical':'original';queueBed(newBed(k,sd,src))});setStatus(`Generating ${n} beds for ${fmt(s.start)}–${fmt(s.start+s.voiceLength)} · ${s.duration}s`);render()}"""+h[j:]
